package com.shelter.api.medical;
import com.shelter.api.animal.Animal; import jakarta.persistence.*; import java.time.LocalDate; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="dewormings") public class Deworming {
 @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="animal_id",nullable=false) private Animal animal; @Column(name="product_name",nullable=false,length=160) private String productName; private String treatmentType; @Column(nullable=false) private LocalDate administeredDate; private LocalDate nextDueDate; private String dose; private String veterinarian; @Column(columnDefinition="TEXT") private String notes; private String createdBy; private OffsetDateTime createdAt;
 @PrePersist void create(){if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=OffsetDateTime.now();}
 public UUID getId(){return id;} public Animal getAnimal(){return animal;} public void setAnimal(Animal v){animal=v;} public String getProductName(){return productName;} public void setProductName(String v){productName=v;} public String getTreatmentType(){return treatmentType;} public void setTreatmentType(String v){treatmentType=v;} public LocalDate getAdministeredDate(){return administeredDate;} public void setAdministeredDate(LocalDate v){administeredDate=v;} public LocalDate getNextDueDate(){return nextDueDate;} public void setNextDueDate(LocalDate v){nextDueDate=v;} public String getDose(){return dose;} public void setDose(String v){dose=v;} public String getVeterinarian(){return veterinarian;} public void setVeterinarian(String v){veterinarian=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;} public String getCreatedBy(){return createdBy;} public void setCreatedBy(String v){createdBy=v;} public OffsetDateTime getCreatedAt(){return createdAt;}
}